fn redact_sensitive_provider_output(text: &str, mcp_token: &str) -> String {
    let mut redacted = if mcp_token.is_empty() {
        text.to_owned()
    } else {
        text.replace(mcp_token, "[REDACTED]")
    };
    for marker in [
        "GAMEENGINE_MCP_AUTH_TOKEN=",
        "Authorization: Bearer ",
        "authorization: bearer ",
        "api_key=",
        "API_KEY=",
        "token=",
        "TOKEN=",
    ] {
        if let Some(index) = redacted.find(marker) {
            let value_start = index + marker.len();
            let value_end = redacted[value_start..]
                .find(char::is_whitespace)
                .map_or(redacted.len(), |offset| value_start + offset);
            redacted.replace_range(value_start..value_end, "[REDACTED]");
        }
    }
    redacted
}

